// === Tab: mySketch.js ===
const PIXEL_DENSITY = 2;
let theShader;
let canvas;
let f;
let textGraphic;

let control = {
	tileAmount: 30,
	feather: 0.04,
	display: 0
}

window.onload = function() {
	var gui = new dat.GUI();
	gui.domElement.id = 'gui';
	gui.add(control, 'tileAmount', 1, 100).name("Tile Amount");
	gui.add(control, 'feather', 0, 1).name("Feather");
	gui.add(control, 'display', {Composed: 0, Tile: 1, 'Contour Line': 2, Threshold: 3}).name("Display");
};

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1820721/files/vert.glsl', 'frag.glsl');
	f = loadFont(
    "https://cdnjs.cloudflare.com/ajax/libs/topcoat/0.8.0/font/SourceCodePro-Bold.otf"
  );
}

function setup() {
  pixelDensity(PIXEL_DENSITY);
  canvas = createCanvas(1000,1000, WEBGL);
	background(0);
	noStroke();
	shader(theShader);

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(PIXEL_DENSITY);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(100);
	textGraphic.textAlign(LEFT, CENTER);
	textGraphic.fill("#ffffff");
	textGraphic.text("Halftone", -450, 300);
	textGraphic.text("square", -450, 400);
}

function draw() {
	var y = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-500) / min(1, windowWidth / windowHeight) + 500;

	theShader.setUniform("u_resolution", [width * PIXEL_DENSITY, height * PIXEL_DENSITY]);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * PIXEL_DENSITY, (height-y) * PIXEL_DENSITY]);
  theShader.setUniform("u_time", millis() / 1000.0);
	theShader.setUniform("u_text", textGraphic);
	theShader.setUniform("u_tile_amount", control.tileAmount);
	theShader.setUniform("u_feather", control.feather);
	theShader.setUniform("u_display", control.display);

  rect(width * -0.5, height * -0.5, width, height);
}

// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform sampler2D u_text;
uniform float u_tile_amount;
uniform float u_feather;
uniform int u_display;

float rand(vec2 co){
  return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
}

float smin(float d1, float d2, float k) {
    return -log(exp(-k * d1) + exp(-k * d2)) / k;
}

void main() {
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;
	vec2 mouse = u_mouse / u_resolution.xy;

	vec2 gv = fract(uv * u_tile_amount + .25);

	float box1 = distance(gv, vec2(0., 1.));
	float box3 = distance(gv, vec2(1., 1.));
	float box5 = distance(gv, vec2(.5, .5));
	float box7 = distance(gv, vec2(.0, .0));
	float box9 = distance(gv, vec2(1., 0.));

	float box2 = distance(gv, vec2(.5, 1.));
	float box4 = distance(gv, vec2(.0, .5));
	float box6 = distance(gv, vec2(1., .5));
	float box8 = distance(gv, vec2(.5, .0));

	float k = 32.;

	float b; 
	b = smin(box2, box4, k);
	b = smin(b, box6, k);
	b = smin(b, box8, k);

	float br;
	br = smin(box1, box3, k);
	br = smin(br, box5, k);
	br = smin(br, box7, k);
	br = smin(br, box9, k);

	float tile = smin(b, 1.-br, 1.);

	tile = (tile + .47) * 2.;     // -0.47 ~ 0.03 => 0 ~ 1

	float t1 = sin(u_time - (uv.x*2.)) * .5 + .5;
	float t2 = sin(u_time - (uv.y*5.)) * .5 + .5;
	float threshold = mix(t1, t2, .5);

	float m = 1. - distance(uv, mouse) * 5.;
	m = max(0., m);
	m *= step(m, 1.);

	threshold = threshold + m - 2. * threshold * m;

	float noise = rand(uv) * u_feather * .5 - u_feather * .25;
	threshold += noise;

	float composed = step(tile, threshold);

	float c = composed;

	if(u_display == 1) {
		c = tile;
	}
	if(u_display == 2) {
		float line = step(fract(tile*10.), .2);
		float fill = floor(tile*10.) / 10.;
		c = mix(fill, 1., line);
	}
	if(u_display == 3) {
		c = threshold;
	}


	vec2 text_uv = uv;
	text_uv.y = 1.-text_uv.y;
	float text = texture2D(u_text, text_uv).r;
	text = step(.5, text);

	if(u_display == 0) {
		c = c + text - 2. * c * text;
	}

	vec3 color1 = vec3(1., .92, .98);
	vec3 color2 = vec3(0., .3, .24);

	vec3 col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

// === Tab: vert.glsl ===
 attribute vec3 aPosition;
 attribute vec2 aTexCoord;
 uniform mat4 uProjectionMatrix;
 uniform mat4 uModelViewMatrix;
 varying vec2 vTexCoord;

 void main() {
	 vTexCoord = aTexCoord;
	 vec4 position = vec4(aPosition, 1.0);
	 gl_Position = uProjectionMatrix * uModelViewMatrix * position;
 }

